package models

import "gorm.io/datatypes"

// Board — resource generated by tools/gen-resource.mjs (Item pattern:
// ownership by user_id). Each user only sees/changes their own records.
type Board struct {
	BaseModel

	// Owner of the record. Every access is filtered by this field (from the JWT).
	UserID string `gorm:"type:uuid;index;not null" json:"user_id"`

	Title       string `gorm:"type:varchar(200);not null" json:"title"`
	Description string `gorm:"type:text" json:"description"`
	Status      string `gorm:"type:varchar(20);index;default:'active'" json:"status"`

	// Data — serialized snapshot of the board (OpenBoard JSON: elements,
	// camera, appearance...). datatypes.JSON is stored as JSONB in Postgres.
	Data datatypes.JSON `gorm:"type:jsonb" json:"data"`
}

// TableName pins the table name (keeps model, indexes and migration consistent).
func (Board) TableName() string { return "boards" }

// ValidBoardStatus validates the status. Adjust the values to your domain.
func ValidBoardStatus(s string) bool {
	switch s {
	case "active", "archived", "done":
		return true
	}
	return false
}
